CSS = """:root{--g:#2f6b3a;--gd:#1f4a28;--bg:#f3f5f1;--line:#d8ddd2;--ink:#21251f}*{box-sizing:border-box}
body{margin:0;font-family:system-ui,sans-serif;background:var(--bg);color:var(--ink);line-height:1.5}
aside{background:var(--gd);color:#fff;padding:10px 14px;display:flex;flex-wrap:wrap;gap:4px 14px;align-items:center}
aside a,aside button{color:#fff;text-decoration:none;padding:4px 0;background:none;border:0;font:inherit;cursor:pointer;margin:0}aside b{margin-right:auto}
main{padding:16px;max-width:980px;margin:auto;width:100%}
@media(min-width:860px){body{display:flex}aside{flex-direction:column;align-items:stretch;width:210px;min-height:100vh;position:sticky;top:0;align-self:flex-start;padding:18px}aside b{margin:0 0 14px}}
h1{font-size:24px;margin:4px 0 14px}h2{font-size:18px}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px;margin-bottom:16px}
.card,.box{background:#fff;border:1px solid var(--line);border-radius:8px;padding:14px;margin-bottom:12px}.card b{display:block;font-size:26px;color:var(--gd)}
table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:8px;border-bottom:1px solid var(--line);text-align:left;font-size:14px;vertical-align:top}.scroll{overflow-x:auto}
label{display:block;font-weight:600;font-size:14px;margin:10px 0 0}
input,select,textarea{width:100%;font:inherit;padding:9px;border:1px solid #b5bcab;border-radius:6px;background:#fff;margin-top:3px}textarea{min-height:90px}
button,.btn{background:var(--g);color:#fff;border:0;border-radius:6px;padding:9px 14px;font:inherit;font-weight:600;cursor:pointer;text-decoration:none;display:inline-block;margin:8px 6px 0 0}
.alt{background:#e2e7dc!important;color:var(--ink)!important}.bad{background:#b42318!important;color:#fff!important}
.tag{font-size:12px;padding:2px 8px;border-radius:99px;background:#e2e7dc}.over{background:#fbe4e1;color:#b42318}.td{background:#fdf1d6;color:#8a5a00}.demo{background:#fdf1d6}
.flash,.dm{background:#e3f1e2;border:1px solid #9cc79a;padding:10px;border-radius:6px;margin-bottom:12px}.dm{background:#fdf1d6;border-color:#e3c36a}
.g2{display:grid;gap:0 14px;grid-template-columns:repeat(auto-fit,minmax(190px,1fr))}.pre{white-space:pre-wrap}
:focus-visible{outline:3px solid #f0b429}@media print{aside,.np{display:none}body{background:#fff}}"""
M = """{% macro f(n,l,v='',t='text',ex='') %}<label>{{l}}<input name="{{n}}" type="{{t}}" value="{{v if v is not none}}" {{ex|safe}}></label>{% endmacro %}
{% macro sel(n,l,o,c='') %}<label>{{l}}<select name="{{n}}">{% for x in o %}<option {{'selected' if x==c}}>{{x}}</option>{% endfor %}</select></label>{% endmacro %}
{% macro copy(id) %}<button type="button" class="alt np" onclick="navigator.clipboard.writeText(document.getElementById('{{id}}').innerText);this.textContent='Copied'">Copy</button>{% endmacro %}"""
BASE = """<!doctype html><html lang=en><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><meta name=robots content="noindex">
<title>LandscapeDesk</title><style>""" + CSS + """</style><body>
{% if u %}<aside><b>{% if s.logo %}<img src="{{s.logo}}" alt="" height=22> {% endif %}{{s.biz_name or 'LandscapeDesk'}}</b>
<a href="/">Dashboard</a><a href="/leads">Leads</a><a href="/followups">Follow up today</a><a href="/quotes">Quotes</a><a href="/replies">Quick replies</a><a href="/reviews">Reviews</a><a href="/settings">Settings</a>
{% if u.role=='admin' %}<a href="/admin">Owner admin</a>{% endif %}<form method=post action="/logout">{{csrf}}<button>Log out</button></form></aside>{% endif %}
<main>{% if u and u.is_demo %}<div class=dm>Demo account. All data is fictional and nothing is sent to customers. Access ends {{u.demo_expires}}.</div>{% endif %}
{% for m in get_flashed_messages() %}<div class=flash role=status>{{m}}</div>{% endfor %}{% block c %}{% endblock %}</main></html>"""
H = '{% extends "base.html" %}{% from "m.html" import f,sel,copy %}{% block c %}'
E = "{% endblock %}"
T = {"base.html": BASE, "m.html": M,
"login.html": H + '<div class=box style="max-width:380px;margin:40px auto"><h1>LandscapeDesk</h1><form method=post>{{csrf}}{{f("email","Email","","email","required")}}{{f("password","Password","","password","required")}}<button>Sign in</button> <a href="/request-access">Request access</a></form></div>' + E,
"access.html": H + '<div class=box style="max-width:380px;margin:40px auto"><h1>Request access</h1><p>Access is by approval from the owner.</p><form method=post>{{csrf}}{{f("biz","Business name")}}{{f("email","Email","","email","required")}}{{f("password","Password (10+ characters)","","password","required minlength=10")}}<button>Send request</button></form></div>' + E,
"dash.html": H + """<h1>Dashboard</h1><div class=cards>
{% for k,v in [('Total leads',st.total),('New leads',st.new),('Follow-ups today',st.due),('Overdue',st.over),('Quotes sent',st.sent),('Awaiting reply',st.wait),('Jobs won',st.won),('Jobs lost',st.lost),('Quoted value',s.currency~'{:,.0f}'.format(st.sent_v)),('Won value',s.currency~'{:,.0f}'.format(st.won_v)),('Conversion',st.rate)] %}<div class=card><b>{{v}}</b>{{k}}</div>{% endfor %}</div>
<div class=g2><div class=box><h2>Upcoming follow-ups</h2>{% for l in up %}<p><a href="/leads/{{l.id}}">{{l.name}}</a> <span class="tag {{'over' if l.follow<today else 'td' if l.follow==today}}">{{l.follow}}</span></p>{% else %}<p>None scheduled.</p>{% endfor %}</div>
<div class=box><h2>Recent activity</h2>{% for a in act %}<p><b>{{a.k}}</b> {{a.t[:60]}} <small>{{a.d[:10]}}</small></p>{% else %}<p>No activity yet. <a href="/leads/new">Add your first lead</a>.</p>{% endfor %}</div></div>""" + E,
"leads.html": H + """<h1>Leads</h1><a class=btn href="/leads/new">New lead</a><form class=box method=get><div class=g2>{{f("q","Search",s)}}<label>Status<select name=status><option value="">All</option>{% for x in statuses %}<option {{'selected' if x==st}}>{{x}}</option>{% endfor %}</select></label></div><button>Filter</button></form>
<div class=scroll><table><tr><th>Name<th>Service<th>Status<th>Follow-up<th>Value</tr>{% for l in rows %}<tr><td><a href="/leads/{{l.id}}">{{l.name}}</a>{% if l.is_demo %} <span class="tag demo">DEMO</span>{% endif %}<td>{{l.service}}<td>{{l.status}}<td>{{l.follow}}<td>{{s.currency}}{{'{:,.0f}'.format(l.value)}}</tr>{% else %}<tr><td colspan=5>No leads match. Add one to get started.</tr>{% endfor %}</table></div>""" + E,
"followups.html": H + """<h1>Follow up today</h1><div class=box><h2>Overdue</h2>{% for l in over %}<p><span class="tag over">overdue {{l.follow}}</span> <a href="/leads/{{l.id}}">{{l.name}}</a> {{l.phone}}</p>{% else %}<p>Nothing overdue.</p>{% endfor %}</div>
<div class=box><h2>Due today</h2>{% for l in due %}<p><span class="tag td">today</span> <a href="/leads/{{l.id}}">{{l.name}}</a> {{l.phone}}</p>{% else %}<p>Nothing due today.</p>{% endfor %}</div>""" + E,
"lead.html": H + """<h1>{{l.name if l else 'New lead'}}</h1><form class=box method=post>{{csrf}}<div class=g2>{{f("name","Customer name",l.name if l else '',"text","required")}}{{f("phone","Phone",l.phone if l else '')}}{{f("email","Email",l.email if l else '')}}
<label>Service<input name=service list=sv value="{{l.service if l else ''}}"><datalist id=sv>{% for x in sv %}<option>{{x}}</option>{% endfor %}</datalist></label>{{f("address","Address / location",l.address if l else '')}}
{{sel("status","Status",statuses,l.status if l else 'New')}}{{f("follow","Follow-up date",l.follow if l else '',"date")}}{{f("value","Estimated value",l.value if l else 0,"number",'step=any min=0')}}</div>
<label>Notes<textarea name=notes>{{l.notes if l else ''}}</textarea></label><button>Save</button></form>
{% if l %}<a class=btn href="/quotes/new?lead={{l.id}}">New quote</a><a class="btn alt" href="/reviews?lead={{l.id}}">Review request</a>
<form method=post action="/leads/{{l.id}}/delete" style="display:inline" onsubmit="return confirm('Delete this lead and its quotes?')">{{csrf}}<button class=bad>Delete</button></form>
<div class=box><h2>Interactions</h2><form method=post action="/leads/{{l.id}}/note">{{csrf}}<textarea name=text placeholder="Record a call, message or visit" required></textarea><button>Add note</button></form>{% for n in notes %}<p><small>{{n.created[:16]}}</small> {{n.text}}</p>{% endfor %}</div>
<div class=box><h2>Quotes</h2>{% for x in qs %}<p><a href="/quotes/{{x.id}}">{{x.service}}</a> {{s.currency}}{{'{:,.2f}'.format(x.final)}} {{x.status}}</p>{% else %}<p>None yet.</p>{% endfor %}</div>{% endif %}""" + E,
"quotes.html": H + """<h1>Quotes</h1><a class=btn href="/quotes/new">New quote</a><form class=box method=get><div class=g2>{{f("q","Search",s)}}<label>Status<select name=status><option value="">All</option>{% for x in qst %}<option {{'selected' if x==st}}>{{x}}</option>{% endfor %}</select></label></div><button>Filter</button></form>
<div class=scroll><table><tr><th>Customer<th>Service<th>Amount<th>Created<th>Sent<th>Expires<th>Status</tr>{% for r in rows %}<tr><td><a href="/quotes/{{r.id}}">{{r.name}}</a><td>{{r.service}}<td>{{s.currency}}{{'{:,.2f}'.format(r.final)}}<td>{{r.created[:10]}}<td>{{r.sent}}<td>{{r.expires}}<td>{{r.status}}</tr>{% else %}<tr><td colspan=7>No quotes yet.</tr>{% endfor %}</table></div>""" + E,
"qform.html": H + """<h1>{{'Edit quote' if qt else 'Quick quote'}}</h1><form class=box method=post>{{csrf}}<div class=g2>
<label>Customer (lead)<select name=lead_id required><option value="">Choose a lead</option>{% for x in ls %}<option value="{{x.id}}" {{'selected' if x.id==lid}}>{{x.name}}</option>{% endfor %}</select></label>
<label>Service<input name=service list=sv value="{{d.service or ''}}" required><datalist id=sv>{% for x in sv %}<option>{{x}}</option>{% endfor %}</datalist></label>
{{f("size","Lawn / garden size",d.size)}}{{sel("cx","Complexity (labor x1.00 / 1.15 / 1.35)",cxs,d.cx)}}
{{f("hours","Labor hours per worker",d.hours,"number",'step=any min=0')}}{{f("workers","Number of workers",d.workers,"number",'step=any min=1')}}{{f("rate","Labor rate per hour",d.rate,"number",'step=any min=0')}}
{{f("materials","Material costs (markup from Settings)",d.materials,"number",'step=any min=0')}}{{f("equipment","Equipment costs",d.equipment,"number",'step=any min=0')}}{{f("travel","Travel expenses",d.travel,"number",'step=any min=0')}}
{{f("other","Additional expenses",d.other,"number",'step=any min=0')}}{{f("margin","Desired profit margin %",d.margin,"number",'step=any min=0 max=80')}}{{f("override","Manual final price (optional)",d.override,"number",'step=any min=0')}}</div>
<label>Job description<textarea name=desc>{{d.desc or ''}}</textarea></label><button>Calculate and save</button></form>""" + E,
"qview.html": H + """<h1>Quote for {{lead.name}}</h1><div class=box>{% if s.logo %}<img src="{{s.logo}}" alt="" height=40>{% endif %}<h2>{{s.biz_name}}</h2><p>{{s.phone}} {{s.email}}</p><p><b>Customer:</b> {{lead.name}} {{lead.address}}</p>
<p><b>Service:</b> {{qt.service}}</p><p class=pre>{{d.desc}}</p>
<table>{% for k,v in [('Labor',qt.labor),('Materials (incl. markup)',qt.mat),('Equipment, travel, other',qt.other),('Total cost',qt.cost)] %}<tr><td>{{k}}<td>{{s.currency}}{{'{:,.2f}'.format(v)}}</tr>{% endfor %}</table>
<p class=np>Range: {{s.currency}}{{'{:,.2f}'.format(qt.low)}} (low) / {{s.currency}}{{'{:,.2f}'.format(qt.rec)}} (recommended) / {{s.currency}}{{'{:,.2f}'.format(qt.high)}} (high)</p>
<h2>Final price: {{s.currency}}{{'{:,.2f}'.format(qt.final)}}</h2><p>Valid until {{exp}}</p><p><small class=pre>{{s.terms}}</small></p></div>
<div class="box np"><h2>Message</h2><p class=pre id=m>{{msg}}</p>{{copy('m')}}<button type=button class=alt onclick="window.print()">Print / save as PDF</button><a class="btn alt" href="/quotes/{{qt.id}}/edit">Edit</a>
<form method=post action="/quotes/{{qt.id}}/status">{{csrf}}{{sel("status","Status ("~qt.status~")",qst,qt.status)}}<button>Update status</button></form>
<form method=post action="/quotes/{{qt.id}}/won" style="display:inline">{{csrf}}<button class=alt>Mark lead Won at this price</button></form>
<form method=post action="/quotes/{{qt.id}}/delete" style="display:inline" onsubmit="return confirm('Delete this quote?')">{{csrf}}<button class=bad>Delete</button></form></div>""" + E,
"replies.html": H + """<h1>Quick replies</h1><form class=box method=get><div class=g2>{{f("q","Search",s)}}<label>Fill in for<select name=lead><option value="">(no customer)</option>{% for x in ls %}<option value="{{x.id}}" {{'selected' if x.id==lid}}>{{x.name}}</option>{% endfor %}</select></label></div><button>Apply</button></form>
{% for r in rows %}<div class=box><b>{{r.title}}</b> <span class=tag>{{r.cat}}</span><p class=pre id="r{{r.id}}">{{r.shown}}</p>{{copy('r'~r.id)}}
<details><summary>Edit</summary><form method=post>{{csrf}}<input type=hidden name=act value=edit><input type=hidden name=id value="{{r.id}}">{{f("cat","Category",r.cat)}}{{f("title","Title",r.title)}}<label>Text<textarea name=body>{{r.body}}</textarea></label><button>Save</button></form>
<form method=post onsubmit="return confirm('Delete this reply?')">{{csrf}}<input type=hidden name=act value=delete><input type=hidden name=id value="{{r.id}}"><button class=bad>Delete</button></form></details></div>{% else %}<p>No replies match.</p>{% endfor %}
<details class=box><summary><b>Add a reply</b></summary><form method=post>{{csrf}}{{f("cat","Category")}}{{f("title","Title","","text","required")}}<label>Text (use [Customer Name], [Business Name], [Service Area])<textarea name=body required></textarea></label><button>Add</button></form></details>""" + E,
"reviews.html": H + """<h1>Review requests</h1><form class=box method=get><label>Customer<select name=lead>{% for x in ls %}<option value="{{x.id}}" {{'selected' if lead and x.id==lead.id}}>{{x.name}}</option>{% endfor %}</select></label><button>Generate message</button></form>
{% if lead %}<div class=box><p class=pre id=rm>{{msg}}</p>{{copy('rm')}}<form method=post style="display:inline">{{csrf}}<input type=hidden name=lead_id value="{{lead.id}}"><input type=hidden name=status value=Prepared><button class=alt>Record as prepared</button></form>
<form method=post style="display:inline">{{csrf}}<input type=hidden name=lead_id value="{{lead.id}}"><input type=hidden name=status value=Sent><button class=alt>Record as sent</button></form><p><small>Messages are never sent automatically. Copy and send it yourself.</small></p></div>{% endif %}
<div class=box><h2>History</h2>{% for r in log %}<p>{{r.name}}: {{r.status}} <small>{{r.created[:10]}}</small></p>{% else %}<p>Nothing recorded yet.</p>{% endfor %}</div>""" + E,
"settings.html": H + """<h1>Settings</h1><form class=box method=post>{{csrf}}<div class=g2>{{f("biz_name","Business name",s.biz_name)}}{{f("logo","Logo image URL",s.logo)}}{{f("phone","Phone",s.phone)}}{{f("email","Email",s.email)}}{{f("area","Service area",s.area)}}{{f("hours","Opening hours",s.hours)}}{{f("currency","Currency symbol",s.currency)}}
{{f("rate","Default labor rate / hour",s.rate,"number",'step=any min=0')}}{{f("markup","Material markup %",s.markup,"number",'step=any min=0')}}{{f("margin","Default profit margin %",s.margin,"number",'step=any min=0 max=80')}}{{f("quote_days","Quote valid for (days)",s.quote_days,"number",'min=1')}}{{f("review_link","Review link",s.review_link)}}</div>
<label>Services, one per line as Name|default price<textarea name=services>{{s.services}}</textarea></label><label>Quote terms<textarea name=terms>{{s.terms}}</textarea></label><label>Review request template<textarea name=review_tpl>{{s.review_tpl}}</textarea></label><button>Save settings</button></form>""" + E,
"admin.html": H + """<h1>Owner admin</h1><form class=box method=post action="/admin/create">{{csrf}}<h2>Create account</h2><div class=g2>{{f("biz","Business")}}{{f("email","Email","","email","required")}}{{f("password","Temporary password (10+)","","text","required minlength=10")}}{{sel("mode","Type",["demo","real"])}}{{f("days","Demo days","7","number","min=1")}}</div><button>Create</button></form>
{% for x in users %}<div class=box><b>{{x.email}}</b> {{x.biz_name}} <span class=tag>{{x.role}}</span> <span class=tag>{{x.status}}</span>{% if x.is_demo %} <span class="tag demo">demo until {{x.demo_expires or 'not set'}}</span>{% endif %}
{% if x.role!='admin' %}<div>{% for a,l in [('approve','Approve'),('reject','Reject'),('revoke','Revoke now'),('enable','Enable'),('paying','Make paying')] %}<form method=post action="/admin/{{x.id}}/{{a}}" style="display:inline">{{csrf}}{% if a=='approve' %}<select name=mode style="width:auto"><option>demo</option><option>real</option></select><input name=days value=7 type=number style="width:70px">{% endif %}<button class="{{'bad' if a=='revoke' else 'alt'}}">{{l}}</button></form>{% endfor %}
<form method=post action="/admin/{{x.id}}/expiry" style="display:inline">{{csrf}}<input type=date name=date value="{{x.demo_expires}}" style="width:auto"><button class=alt>Set demo expiry</button></form></div>{% endif %}</div>{% endfor %}""" + E}
